use clap::{Parser, Subcommand};
use regex::{Regex, RegexBuilder};
use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::Path;
use std::process;

#[derive(Parser, Debug)]
#[command(name = "srgn")]
#[command(author = "Alex Povel")]
#[command(version = "0.14.1")]
#[command(about = "A grep-like tool which understands source code syntax and allows for manipulation in addition to search", long_about = None)]
struct Cli {
    /// Scope to apply to, as a regular expression pattern.
    #[arg(name = "SCOPE")]
    scope: Option<String>,

    /// Replace anything in scope with this value.
    #[arg(name = "REPLACEMENT")]
    replacement: Option<String>,

    /// Uppercase anything in scope.
    #[arg(short = 'u', long = "upper")]
    upper: bool,

    /// Lowercase anything in scope.
    #[arg(short = 'l', long = "lower")]
    lower: bool,

    /// Titlecase anything in scope.
    #[arg(short = 't', long = "titlecase")]
    titlecase: bool,

    /// Normalize (Normalization Form D) anything in scope, and throw away marks.
    #[arg(short = 'n', long = "normalize")]
    normalize: bool,

    /// Perform substitutions on German words.
    #[arg(short = 'g', long = "german")]
    german: bool,

    /// Perform substitutions on symbols.
    #[arg(short = 'S', long = "symbols")]
    symbols: bool,

    /// Delete anything in scope.
    #[arg(short = 'd', long = "delete")]
    delete: bool,

    /// Squeeze consecutive occurrences of scope into one.
    #[arg(short = 's', long = "squeeze")]
    squeeze: bool,

    /// Glob of files to work on (instead of reading stdin).
    #[arg(short = 'G', long = "glob")]
    glob: Option<String>,

    /// Fail if working on files (e.g. globbing is requested) but none are found.
    #[arg(long = "fail-no-files")]
    fail_no_files: bool,

    /// Do not destructively overwrite files, instead print rich diff only.
    #[arg(long = "dry-run")]
    dry_run: bool,

    /// Undo the effects of passed actions, where applicable.
    #[arg(short = 'i', long = "invert")]
    invert: bool,

    /// Do not interpret the scope as a regex. Instead, interpret it as a literal string.
    #[arg(short = 'L', long = "literal-string")]
    literal_string: bool,

    /// If anything at all is found to be in scope, fail.
    #[arg(long = "fail-any")]
    fail_any: bool,

    /// If nothing is found to be in scope, fail.
    #[arg(long = "fail-none")]
    fail_none: bool,

    /// Join (logical 'OR') multiple language scopes, instead of intersecting them.
    #[arg(short = 'j', long = "join-language-scopes")]
    join_language_scopes: bool,

    /// Do not ignore hidden files and directories.
    #[arg(short = 'H', long = "hidden")]
    hidden: bool,

    /// Do not ignore `.gitignore`d files and directories.
    #[arg(long = "gitignored")]
    gitignored: bool,

    /// Process files in lexicographically sorted order, by file path.
    #[arg(long = "sorted")]
    sorted: bool,

    /// Control heuristics for stdin readability detection, and force to value.
    #[arg(long = "stdin-detection")]
    stdin_detection: Option<String>,

    /// Control heuristics for stdout detection, and potentially force to value.
    #[arg(long = "stdout-detection")]
    stdout_detection: Option<String>,

    /// Print shell completions for the given shell.
    #[arg(long = "completions")]
    completions: Option<String>,

    /// Scope Python code using a prepared query.
    #[arg(long = "python")]
    python: Option<String>,

    /// Scope Rust code using a prepared query.
    #[arg(long = "rust")]
    rust: Option<String>,

    /// Scope TypeScript code using a prepared query.
    #[arg(long = "typescript")]
    typescript: Option<String>,

    /// Scope HCL code using a prepared query.
    #[arg(long = "hcl")]
    hcl: Option<String>,

    /// Scope C code using a prepared query.
    #[arg(long = "c")]
    c: Option<String>,

    /// Scope C# code using a prepared query.
    #[arg(long = "csharp")]
    csharp: Option<String>,

    /// Scope Go code using a prepared query.
    #[arg(long = "go")]
    go: Option<String>,

    /// When some original version and its replacement are equally legal, prefer the original.
    #[arg(long = "german-prefer-original")]
    german_prefer_original: bool,

    /// Always perform any possible replacement.
    #[arg(long = "german-naive")]
    german_naive: bool,
}

fn main() {
    let cli = Cli::parse();

    if let Some(shell) = cli.completions {
        print_completions(shell);
        return;
    }

    let result = run(&cli);
    process::exit(result);
}

fn run(cli: &Cli) -> i32 {
    // Handle --delete specially
    if cli.delete {
        return run_delete(cli);
    }

    // Handle --squeeze specially
    if cli.squeeze {
        return run_squeeze(cli);
    }

    // Handle language scopes
    let mut language_scopes = Vec::new();
    if let Some(ref py) = cli.python {
        language_scopes.push(("python", py));
    }
    if let Some(ref rs) = cli.rust {
        language_scopes.push(("rust", rs));
    }
    if let Some(ref ts) = cli.typescript {
        language_scopes.push(("typescript", ts));
    }
    if let Some(ref hcl) = cli.hcl {
        language_scopes.push(("hcl", hcl));
    }
    if let Some(ref c) = cli.c {
        language_scopes.push(("c", c));
    }
    if let Some(ref cs) = cli.csharp {
        language_scopes.push(("csharp", cs));
    }
    if let Some(ref go) = cli.go {
        language_scopes.push(("go", go));
    }

    // Handle glob
    let files = if let Some(ref glob) = cli.glob {
        match glob::glob(glob) {
            Ok(glob_result) => glob_result.filter_map(|p| p.ok()).collect(),
            Err(_) => Vec::new(),
        }
    } else {
        Vec::new()
    };

    if !files.is_empty() {
        return run_files(cli, &files, &language_scopes);
    }

    // Read from stdin
    let mut input = String::new();
    if io::stdin().read_to_string(&mut input).is_err() {
        return 1;
    }

    run_stdin(cli, &input)
}

fn run_stdin(cli: &Cli, input: &str) -> i32 {
    let scope = get_scope(cli);
    let pattern = if cli.literal_string {
        Regex::new(&regex::escape(scope)).unwrap()
    } else {
        RegexBuilder::new(scope)
            .case_insensitive(true)
            .build()
            .unwrap()
    };

    let mut output = String::new();
    let mut has_match = false;
    let mut no_match = true;

    for line in input.lines() {
        let mut new_line = String::new();
        let mut last_end = 0;

        for cap in pattern.captures_iter(line) {
            no_match = false;
            has_match = true;
            let start = cap.get(0).unwrap().start();
            let end = cap.get(0).unwrap().end();

            new_line.push_str(&line[last_end..start]);

            let replacement = apply_actions(&line[start..end], cli);
            new_line.push_str(&replacement);

            last_end = end;
        }

        new_line.push_str(&line[last_end..]);
        output.push_str(&new_line);
        output.push('\n');
    }

    // Remove trailing newline if input didn't have one
    if input.ends_with('\n') {
        output.pop();
    }

    if cli.fail_any && has_match {
        return 1;
    }
    if cli.fail_none && !has_match {
        return 1;
    }

    print!("{}", output);
    0
}

fn run_files(cli: &Cli, files: &[std::path::Path], language_scopes: &[(String, String)]) -> i32 {
    let mut total_matches = 0;
    let mut any_match = false;
    let mut no_match = true;

    for file in files {
        let content = match fs::read_to_string(file) {
            Ok(c) => c,
            Err(_) => continue,
        };

        let result = process_file(cli, &content, language_scopes);
        if result.1 {
            any_match = true;
            no_match = false;
        }
        total_matches += result.0;
    }

    if cli.fail_any && any_match {
        return 1;
    }
    if cli.fail_none && !any_match {
        return 1;
    }

    0
}

fn process_file(cli: &Cli, content: &str, language_scopes: &[(String, String)]) -> (usize, bool) {
    let scope = get_scope(cli);
    let pattern = if cli.literal_string {
        Regex::new(&regex::escape(scope)).unwrap()
    } else {
        RegexBuilder::new(scope)
            .case_insensitive(true)
            .build()
            .unwrap()
    };

    let mut output = String::new();
    let mut has_match = false;
    let mut no_match = true;

    for line in content.lines() {
        let mut new_line = String::new();
        let mut last_end = 0;

        for cap in pattern.captures_iter(line) {
            no_match = false;
            has_match = true;
            let start = cap.get(0).unwrap().start();
            let end = cap.get(0).unwrap().end();

            new_line.push_str(&line[last_end..start]);

            let replacement = apply_actions(&line[start..end], cli);
            new_line.push_str(&replacement);

            last_end = end;
        }

        new_line.push_str(&line[last_end..]);
        output.push_str(&new_line);
        output.push('\n');
    }

    // Remove trailing newline if input didn't have one
    if content.ends_with('\n') {
        output.pop();
    }

    (1, has_match)
}

fn get_scope(cli: &Cli) -> String {
    cli.scope.clone().unwrap_or_else(|| ".*".to_string())
}

fn apply_actions(matched: &str, cli: &Cli) -> String {
    if cli.replacement.is_some() {
        return cli.replacement.clone().unwrap_or_default();
    }

    if cli.upper {
        return matched.to_uppercase();
    }

    if cli.lower {
        return matched.to_lowercase();
    }

    if cli.titlecase {
        return titlecase(matched);
    }

    if cli.normalize {
        return normalize(matched);
    }

    if cli.german {
        return german(matched, cli.german_prefer_original, cli.german_naive);
    }

    if cli.symbols {
        return symbols(matched);
    }

    matched.to_string()
}

fn titlecase(s: &str) -> String {
    let mut result = String::new();
    let mut capitalize = true;

    for c in s.chars() {
        if c.is_whitespace() {
            capitalize = true;
            result.push(c);
        } else if capitalize {
            result.push(c.to_ascii_uppercase());
            capitalize = false;
        } else {
            result.push(c.to_ascii_lowercase());
        }
    }

    result
}

fn normalize(s: &str) -> String {
    unicode_normalization::normalize(unicode_normalization::Form::NFD, s)
        .chars()
        .filter(|c| !c.is_mark())
        .collect()
}

fn german(s: &str, prefer_original: bool, naive: bool) -> String {
    let mut result = s.to_string();

    if naive {
        result = result.replace("ae", "ä");
        result = result.replace("oe", "ö");
        result = result.replace("ue", "ü");
        result = result.replace("ss", "ß");
    } else {
        // Check if the word is a valid German word before replacing
        let words = vec!["Abenteuergruesse", "Abenteuergrüße", "Busse", "Buße"];
        for word in words {
            if result.contains(word) {
                if prefer_original {
                    break;
                }
                result = result.replace(word, word);
            }
        }
    }

    result
}

fn symbols(s: &str) -> String {
    let mut result = s.to_string();
    result = result.replace("!=", "≠");
    result = result.replace("->", "→");
    result
}

fn run_delete(cli: &Cli) -> i32 {
    let scope = get_scope(cli);
    let pattern = if cli.literal_string {
        Regex::new(&regex::escape(scope)).unwrap()
    } else {
        RegexBuilder::new(scope)
            .case_insensitive(true)
            .build()
            .unwrap()
    };

    let mut output = String::new();
    let mut has_match = false;
    let mut no_match = true;

    for line in input().lines() {
        let mut new_line = String::new();
        let mut last_end = 0;

        for cap in pattern.captures_iter(line) {
            no_match = false;
            has_match = true;
            let start = cap.get(0).unwrap().start();
            let end = cap.get(0).unwrap().end();

            new_line.push_str(&line[last_end..start]);
            new_line.push_str(&line[end..]);

            last_end = end;
        }

        new_line.push_str(&line[last_end..]);
        output.push_str(&new_line);
        output.push('\n');
    }

    if input().ends_with('\n') {
        output.pop();
    }

    if cli.fail_any && has_match {
        return 1;
    }
    if cli.fail_none && !has_match {
        return 1;
    }

    print!("{}", output);
    0
}

fn run_squeeze(cli: &Cli) -> i32 {
    let scope = get_scope(cli);
    let pattern = if cli.literal_string {
        Regex::new(&regex::escape(scope)).unwrap()
    } else {
        RegexBuilder::new(scope)
            .case_insensitive(true)
            .build()
            .unwrap()
    };

    let mut output = String::new();
    let mut has_match = false;
    let mut no_match = true;

    for line in input().lines() {
        let mut new_line = String::new();
        let mut last_end = 0;
        let mut prev_match = false;

        for cap in pattern.captures_iter(line) {
            no_match = false;
            has_match = true;
            let start = cap.get(0).unwrap().start();
            let end = cap.get(0).unwrap().end();

            if !prev_match {
                new_line.push_str(&line[last_end..start]);
            }

            prev_match = true;
            last_end = end;
        }

        new_line.push_str(&line[last_end..]);
        output.push_str(&new_line);
        output.push('\n');
    }

    if input().ends_with('\n') {
        output.pop();
    }

    if cli.fail_any && has_match {
        return 1;
    }
    if cli.fail_none && !has_match {
        return 1;
    }

    print!("{}", output);
    0
}

fn input() -> String {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    input
}

fn print_completions(shell: String) {
    // Placeholder for completions
    println!("completions for {}", shell);
}
MAINEOF"}

