    }

    print!("{}", output);
    0
}

fn run_files(cli: &Cli, files: &[std::path::Path], language_scopes: &[(String, String)]) -> i32 {
    let mut total_matches = 0;
    let mut any_match = false;
    let mut no_match = true;

    for file in files {
        let content = match fs::read_to_string(file) {
            Ok(c) => c,
            Err(_) => continue,
        };

        let result = process_file(cli, &content, language_scopes);
        if result.1 {
            any_match = true;
            no_match = false;
        }
        total_matches += result.0;
    }

    if cli.fail_any && any_match {
        return 1;
    }
    if cli.fail_none && !any_match {
        return 1;
    }

    0
}

fn process_file(cli: &Cli, content: &str, language_scopes: &[(String, String)]) -> (usize, bool) {
    let scope = get_scope(cli);
    let pattern = if cli.literal_string {
        Regex::new(&regex::escape(scope)).unwrap()
    } else {
        RegexBuilder::new(scope)
            .case_insensitive(true)
            .build()
            .unwrap()
    };

    let mut output = String::new();
    let mut has_match = false;
    let mut no_match = true;

    for line in content.lines() {
        let mut new_line = String::new();
        let mut last_end = 0;

        for cap in pattern.captures_iter(line) {
            no_match = false;
            has_match = true;
            let start = cap.get(0).unwrap().start();
            let end = cap.get(0).unwrap().end();

            new_line.push_str(&line[last_end..start]);

            let replacement = apply_actions(&line[start..end], cli);
            new_line.push_str(&replacement);

            last_end = end;
        }

        new_line.push_str(&line[last_end..]);
        output.push_str(&new_line);
        output.push('\n');
    }

    // Remove trailing newline if input didn't have one
    if content.ends_with('\n') {
        output.pop();
    }

    (1, has_match)
}

fn get_scope(cli: &Cli) -> String {
    cli.scope.clone().unwrap_or_else(|| ".*".to_string())
}

fn apply_actions(matched: &str, cli: &Cli) -> String {
    if cli.replacement.is_some() {
        return cli.replacement.clone().unwrap_or_default();
    }

    if cli.upper {
        return matched.to_uppercase();
    }

    if cli.lower {
        return matched.to_lowercase();
    }

    if cli.titlecase {
        return titlecase(matched);
    }

    if cli.normalize {
        return normalize(matched);
    }

    if cli.german {
        return german(matched, cli.german_prefer_original, cli.german_naive);
    }

    if cli.symbols {
        return symbols(matched);
    }

    matched.to_string()
}

fn titlecase(s: &str) -> String {
    let mut result = String::new();
    let mut capitalize = true;

    for c in s.chars() {
        if c.is_whitespace() {
            capitalize = true;
            result.push(c);
        } else if capitalize {
            result.push(c.to_ascii_uppercase());
            capitalize = false;
        } else {
            result.push(c.to_ascii_lowercase());
        }
    }

    result
}

fn normalize(s: &str) -> String {
    unicode_normalization::normalize(unicode_normalization::Form::NFD, s)
        .chars()
        .filter(|c| !c.is_mark())
        .collect()
}

fn german(s: &str, prefer_original: bool, naive: bool) -> String {
    let mut result = s.to_string();

    if naive {
        result = result.replace("ae", "ä");
        result = result.replace("oe", "ö");
        result = result.replace("ue", "ü");
        result = result.replace("ss", "ß");
    } else {
        // Check if the word is a valid German word before replacing
        let words = vec!["Abenteuergruesse", "Abenteuergrüße", "Busse", "Buße"];
        for word in words {
            if result.contains(word) {
                if prefer_original {
                    break;
                }
                result = result.replace(word, word);
            }
        }
    }

    result
}

fn symbols(s: &str) -> String {
    let mut result = s.to_string();
    result = result.replace("!=", "≠");
    result = result.replace("->", "→");
    result
}

fn run_delete(cli: &Cli) -> i32 {
    let scope = get_scope(cli);
    let pattern = if cli.literal_string {
        Regex::new(&regex::escape(scope)).unwrap()
    } else {
        RegexBuilder::new(scope)
            .case_insensitive(true)
            .build()
            .unwrap()
    };

    let mut output = String::new();
    let mut has_match = false;
    let mut no_match = true;

    for line in input().lines() {
        let mut new_line = String::new();
        let mut last_end = 0;

        for cap in pattern.captures_iter(line) {
            no_match = false;
            has_match = true;
            let start = cap.get(0).unwrap().start();
            let end = cap.get(0).unwrap().end();

            new_line.push_str(&line[last_end..start]);
            new_line.push_str(&line[end..]);

            last_end = end;
        }

        new_line.push_str(&line[last_end..]);
        output.push_str(&new_line);
        output.push('\n');
    }

    if input().ends_with('\n') {
        output.pop();
    }

    if cli.fail_any && has_match {
        return 1;
    }
    if cli.fail_none && !has_match {
        return 1;
    }

    print!("{}", output);
    0
}

fn run_squeeze(cli: &Cli) -> i32 {
    let scope = get_scope(cli);
    let pattern = if cli.literal_string {
        Regex::new(&regex::escape(scope)).unwrap()
    } else {
        RegexBuilder::new(scope)
            .case_insensitive(true)
            .build()
            .unwrap()
    };

    let mut output = String::new();
    let mut has_match = false;
    let mut no_match = true;

    for line in input().lines() {
        let mut new_line = String::new();
        let mut last_end = 0;
        let mut prev_match = false;

        for cap in pattern.captures_iter(line) {
            no_match = false;
            has_match = true;
            let start = cap.get(0).unwrap().start();
            let end = cap.get(0).unwrap().end();

            if !prev_match {
                new_line.push_str(&line[last_end..start]);
            }

            prev_match = true;
            last_end = end;
        }

        new_line.push_str(&line[last_end..]);
        output.push_str(&new_line);
        output.push('\n');
    }

    if input().ends_with('\n') {
        output.pop();
    }

    if cli.fail_any && has_match {
        return 1;
    }
    if cli.fail_none && !has_match {
        return 1;
    }

    print!("{}", output);
    0
}

fn input() -> String {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    input
}

fn print_completions(shell: String) {
    // Placeholder for completions
    println!("completions for {}", shell);
}
