use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::Path;
use std::process;

// Simple regex engine for basic patterns
struct SimpleRegex {
    pattern: String,
    case_insensitive: bool,
}

impl SimpleRegex {
    fn new(pattern: &str, case_insensitive: bool) -> Self {
        SimpleRegex {
            pattern: pattern.to_string(),
            case_insensitive,
        }
    }

    fn find_all(&self, text: &str) -> Vec<(usize, usize)> {
        let mut matches = Vec::new();
        let text = if self.case_insensitive {
            text.to_lowercase()
        } else {
            text.to_string()
        };
        let pattern = if self.case_insensitive {
            self.pattern.to_lowercase()
        } else {
            self.pattern.clone()
        };

        let mut start = 0;
        loop {
            match text[start..].find(&pattern) {
                Some(pos) => {
                    let abs_pos = start + pos;
                    matches.push((abs_pos, abs_pos + pattern.len()));
                    start = abs_pos + 1;
                }
                None => break,
            }
        }
        matches
    }

    fn find_all_with_captures(&self, text: &str) -> Vec<(usize, usize, String)> {
        let mut matches = Vec::new();
        let text = if self.case_insensitive {
            text.to_lowercase()
        } else {
            text.to_string()
        };
        let pattern = if self.case_insensitive {
            self.pattern.to_lowercase()
        } else {
            self.pattern.clone()
        };

        let mut start = 0;
        loop {
            match text[start..].find(&pattern) {
                Some(pos) => {
                    let abs_pos = start + pos;
                    let match_text = &text[abs_pos..abs_pos + pattern.len()];
                    matches.push((abs_pos, abs_pos + pattern.len(), match_text.to_string()));
                    start = abs_pos + 1;
                }
                None => break,
            }
        }
        matches
    }
}

