    invert_scope: bool,
}

fn main() {
    let args = Args::parse();

    if let Some(shell) = args.completions {
        print_completions(shell);
        return;
    }

    let result = run(&args);
    process::exit(result);
}

fn run(args: &Args) -> i32 {
    let mut actions = Vec::new();

    if args.delete {
        actions.push(Action::Delete);
    }
    if args.squeeze {
        actions.push(Action::Squeeze);
    }
    if args.upper {
        actions.push(Action::Upper);
    }
    if args.lower {
        actions.push(Action::Lower);
    }
    if args.titlecase {
        actions.push(Action::Titlecase);
    }
    if args.normalize {
        actions.push(Action::Normalize);
    }
    if args.german {
        actions.push(Action::German);
    }
    if args.symbols {
        actions.push(Action::Symbols);
    }

    if let Some(replacement) = &args.replacement {
        actions.insert(0, Action::Replace(replacement.clone()));
    }

    if actions.is_empty() {
        return handle_no_actions(args);
    }

    let scope = get_scope(args);
    let pattern = build_pattern(&scope, args);

    let mut input = String::new();
    let mut output = String::new();

    if let Some(glob_pattern) = &args.glob {
        let files = glob::glob(glob_pattern).unwrap().filter_map(|p| p.ok()).collect::<Vec<_>>();

        if files.is_empty() && args.fail_no_files {
            eprintln!("Error: No files found matching {}", glob_pattern);
            return 1;
        }

        for file in files {
            let content = fs::read_to_string(&file).unwrap_or_default();
            let (modified, changed_lines) = process_content(&content, &pattern, &actions, args);

            if modified {
                if args.dry_run {
                    println!("Would modify: {}", file.display());
                    for (line_num, old, new) in &changed_lines {
                        println!("{}:{}:{} -> {}", line_num, file.display(), old, new);
                    }
                } else {
                    fs::write(&file, &output).unwrap();
                }
            }
        }
    } else {
        io::stdin().read_to_string(&mut input).unwrap();
        let (modified, changed_lines) = process_content(&input, &pattern, &actions, args);
        output = if modified { output } else { input.clone() };
    }

    if args.count {
        println!("{}", count_matches(&input, &pattern));
        return 0;
    }

    if args.only_matching {
        print_matches(&input, &pattern);
        return 0;
    }

    if !args.glob.is_some() {
        print!("{}", output);
    }

    if args.fail_any && count_matches(&input, &pattern) > 0 {
        return 1;
    }
    if args.fail_none && count_matches(&input, &pattern) == 0 {
        return 1;
    }

    0
}

fn handle_no_actions(args: &Args) -> i32 {
    if args.glob.is_some() {
        return 0;
    }
    eprintln!("[2026-08-18T06:37:58.528640Z ERROR srgn] No actions specified, and not in search mode. Will return input unchanged, if any.");
    0
}

fn get_scope(args: &Args) -> String {
    if args.literal_string {
        args.scope.clone().unwrap_or_else(|| "".to_string())
    } else {
        args.scope.clone().unwrap_or_else(|| ".*".to_string())
    }
}

fn build_pattern(scope: &str, args: &Args) -> Regex {
    let pattern = if args.literal_string {
        regex::escape(scope)
    } else {
        scope.to_string()
    };

    RegexBuilder::new(&pattern)
        .case_insensitive(true)
        .multi_line(true)
        .build()
        .unwrap_or_else(|e| {
            eprintln!("Error: Invalid regex: {}", e);
            process::exit(1);
        })
}

fn process_content(content: &str, pattern: &Regex, actions: &[Action], args: &Args) -> (bool, Vec<(usize, String, String)>) {
    let mut changed_lines = Vec::new();
    let mut modified = false;

    let lines: Vec<&str> = content.lines().collect();
    let mut result_lines: Vec<String> = Vec::new();

    for (line_num, line) in lines.iter().enumerate() {
        let processed_line = process_line(line, pattern, actions, args, line_num + 1);
        if processed_line != *line {
            modified = true;
        }
        result_lines.push(processed_line);
    }

    if modified {
        changed_lines = lines.iter().enumerate()
            .filter(|(_, l)| process_line(*l, pattern, actions, args, 0) != *l)
            .map(|(i, l)| (i + 1, l.to_string(), process_line(l, pattern, actions, args, 0)))
            .collect();
    }

    (modified, changed_lines)
}

fn process_line(line: &str, pattern: &Regex, actions: &[Action], args: &Args, line_num: usize) -> String {
    let mut result = line.to_string();

    for action in actions {
        match action {
            Action::Replace(repl) => {
                result = pattern.replace_all(&result, repl).to_string();
            }
            Action::Delete => {
                result = pattern.replace_all(&result, "").to_string();
            }
            Action::Squeeze => {
                result = pattern.split(&result).collect::<Vec<_>>().join("");
            }
            Action::Upper => {
                result = pattern.replace_all(&result, |m: &regex::Match| m.as_str().to_uppercase()).to_string();
            }
            Action::Lower => {
                result = pattern.replace_all(&result, |m: &regex::Match| m.as_str().to_lowercase()).to_string();
            }
            Action::Titlecase => {
                result = pattern.replace_all(&result, |m: &regex::Match| {
                    let s = m.as_str();
                    if s.len() > 0 {
                        let mut chars = s.chars();
                        match chars.next() {
                            None => String::new(),
                            Some(c) => c.to_uppercase().collect::<String>() + chars.as_str().to_lowercase().as_str()
                        }
                    } else {
                        String::new()
                    }
                }).to_string();
            }
            Action::Normalize => {
                result = normalize_unicode(&result);
            }
            Action::German => {
                result = german_substitute(&result);
            }
            Action::Symbols => {
                result = symbols_substitute(&result);
            }
        }
    }

    result
}

fn normalize_unicode(s: &str) -> String {
    use unicode_normalization::UnicodeNormalization;
    s.nfd().filter(|c| !c.is_mark()).collect()
}

fn german_substitute(s: &str) -> String {
    s.replace("ae", "ä")
     .replace("oe", "ö")
     .replace("ue", "ü")
     .replace("ss", "ß")
}

fn symbols_substitute(s: &str) -> String {
    s.replace("!", "¡")
     .replace("=", "≡")
     .replace(">", "→")
     .replace("<", "←")
     .replace("≠", "≠")
}

fn count_matches(content: &str, pattern: &Regex) -> usize {
    pattern.find_iter(content).count()
}

fn print_matches(content: &str, pattern: &Regex) {
    for mat in pattern.find_iter(content) {
        print!("{}", mat.as_str());
    }
}

fn print_completions(shell: String) {
    match shell.as_str() {
        "bash" => {
            println!("complete -F _srgn_completion srgn");
        }
        "zsh" => {
            println!("#compdef srgn");
        }
        _ => {
            eprintln!("Unsupported shell: {}", shell);
            process::exit(1);
        }
    }
}

#[derive(Clone)]
enum Action {
    Replace(String),
    Delete,
    Squeeze,
    Upper,
    Lower,
    Titlecase,
    Normalize,
    German,
    Symbols,
}
